import 'package:flutter/material.dart';
import '../../shared/tokens/tokens.dart';
import '../../shared/widgets/app_state_view.dart';
import '../models/lab_group.dart';
import '../services/practical_teacher_service.dart';
import '../widgets/lab_group_card.dart';
import 'lab_attendance_view.dart';

/// شاشة استعراض وإدارة كافة مجموعات المعامل والشعب العملية (Lab Groups View)
class LabGroupsView extends StatefulWidget {
  final PracticalTeacherService? practicalService;

  const LabGroupsView({
    super.key,
    this.practicalService,
  });

  @override
  State<LabGroupsView> createState() => _LabGroupsViewState();
}

class _LabGroupsViewState extends State<LabGroupsView> {
  late final PracticalTeacherService _service;
  ScreenStateType _state = ScreenStateType.loading;
  List<LabGroup> _allGroups = [];
  List<LabGroup> _filteredGroups = [];
  String _selectedFilter = 'ALL'; // ALL | SOFTWARE | NETWORK | DATABASE | HARDWARE
  String _searchQuery = '';
  String? _errorMessage;

  @override
  void initState() {
    super.initState();
    _service = widget.practicalService ?? PracticalTeacherService();
    _loadGroups();
  }

  Future<void> _loadGroups() async {
    setState(() {
      _state = ScreenStateType.loading;
      _errorMessage = null;
    });

    try {
      final groups = await _service.getLabGroups();
      if (!mounted) return;\n\n      setState(() {\n        _allGroups = groups;\n        _applyFilters();\n        _state = groups.isEmpty ? ScreenStateType.empty : ScreenStateType.success;\n      });\n    } catch (e) {\n      if (!mounted) return;\n      setState(() {\n        _state = ScreenStateType.error;\n        _errorMessage = 'تعذر تحميل مجموعات المعامل: $e';\n      });\n    }\n  }\n\n  void _applyFilters() {\n    List<LabGroup> result = List.from(_allGroups);\n\n    if (_selectedFilter != 'ALL') {\n      result = result.where((g) {\n        switch (_selectedFilter) {\n          case 'SOFTWARE':\n            return g.groupType == LabGroupType.softwareLab;\n          case 'NETWORK':\n            return g.groupType == LabGroupType.networkLab;\n          case 'DATABASE':\n            return g.groupType == LabGroupType.databaseLab;\n          case 'HARDWARE':\n            return g.groupType == LabGroupType.hardwareLab;\n          default:\n            return true;\n        }\n      }).toList();\n    }\n\n    if (_searchQuery.trim().isNotEmpty) {\n      final query = _searchQuery.trim().toLowerCase();\n      result = result.where((g) {\n        return g.groupName.toLowerCase().contains(query) ||\n            g.courseCode.toLowerCase().contains(query) ||\n            g.courseName.toLowerCase().contains(query) ||\n            g.roomName.toLowerCase().contains(query) ||\n            (g.delegateName?.toLowerCase().contains(query) ?? false);\n      }).toList();\n    }\n\n    _filteredGroups = result;\n  }\n\n  void _navigateToLabAttendance(LabGroup group) {\n    Navigator.push(\n      context,\n      MaterialPageRoute(\n        builder: (_) => LabAttendanceView(\n          group: group,\n          sessionId: group.activeSessionId,\n          practicalService: _service,\n        ),\n      ),\n    ).then((_) => _loadGroups());\n  }\n\n  Future<void> _handleStartSession(LabGroup group) async {\n    try {\n      final session = await _service.startLabSession(group, group.roomName);\n      if (!mounted) return;\n      ScaffoldMessenger.of(context).showSnackBar(\n        SnackBar(\n          content: Text('تم بدء جلسة المعمل بنجاح: ${group.groupName}'),\n          backgroundColor: AppColors.success,\n        ),\n      );\n      Navigator.push(\n        context,\n        MaterialPageRoute(\n          builder: (_) => LabAttendanceView(\n            group: group,\n            sessionId: session.id,\n            practicalService: _service,\n          ),\n        ),\n      ).then((_) => _loadGroups());\n    } catch (e) {\n      if (!mounted) return;\n      ScaffoldMessenger.of(context).showSnackBar(\n        SnackBar(\n          content: Text('فشل بدء الجلسة: $e'),\n          backgroundColor: AppColors.error,\n        ),\n      );\n    }\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final theme = Theme.of(context);\n\n    return Scaffold(\n      appBar: AppBar(\n        title: const Text('مجموعات المعامل والشعب'),\n        actions: [\n          IconButton(\n            onPressed: _loadGroups,\n            icon: const Icon(Icons.refresh_rounded),\n            tooltip: 'تحديث',\n          ),\n        ],\n      ),\n      body: AppStateView(\n        state: _state,\n        loadingMessage: 'جاري تحميل قائمة الشعب والمعامل...',\n        emptyTitle: 'لا توجد مجموعات معملية',\n        emptyMessage: 'لم يتم العثور على أي مجموعات مسندة لهذا الفصل الدراسي.',\n        emptyIcon: Icons.biotech_outlined,\n        errorMessage: _errorMessage,\n        onRetry: _loadGroups,\n        child: RefreshIndicator(\n          onRefresh: _loadGroups,\n          child: ListView(\n            padding: AppSpacing.paddingLG,\n            children: [\n              // حقل البحث\n              TextField(\n                decoration: InputDecoration(\n                  hintText: 'البحث باسم المجموعة، رمز المقرر، القاعة، أو المندوب...',\n                  prefixIcon: const Icon(Icons.search_rounded),\n                  suffixIcon: _searchQuery.isNotEmpty\n                      ? IconButton(\n                          onPressed: () {\n                            setState(() {\n                              _searchQuery = '';\n                              _applyFilters();\n                            });\n                          },\n                          icon: const Icon(Icons.clear_rounded),\n                        )\n                      : null,\n                  filled: true,\n                  fillColor: AppColors.surface,\n                  contentPadding: const EdgeInsets.symmetric(horizontal: 16.0, vertical: 12.0),\n                  border: OutlineInputBorder(\n                    borderRadius: BorderRadius.circular(AppRadius.radiusMD),\n                    borderSide: const BorderSide(color: AppColors.border),\n                  ),\n                ),\n                onChanged: (val) {\n                  setState(() {\n                    _searchQuery = val;\n                    _applyFilters();\n                  });\n                },\n              ),\n              AppSpacing.gapVerticalMD,\n              // أزرار التصفية حسب نوع المعمل\n              SingleChildScrollView(\n                scrollDirection: Axis.horizontal,\n                child: Row(\n                  children: [\n                    _buildFilterChip('ALL', 'الكل (${_allGroups.length})'),\n                    AppSpacing.gapHorizontalSM,\n                    _buildFilterChip(\n                      'SOFTWARE',\n                      'معامل البرمجيات (${_allGroups.where((g) => g.groupType == LabGroupType.softwareLab).length})',\n                    ),\n                    AppSpacing.gapHorizontalSM,\n                    _buildFilterChip(\n                      'NETWORK',\n                      'معامل الشبكات (${_allGroups.where((g) => g.groupType == LabGroupType.networkLab).length})',\n                    ),\n                    AppSpacing.gapHorizontalSM,\n                    _buildFilterChip(\n                      'DATABASE',\n                      'معامل البيانات (${_allGroups.where((g) => g.groupType == LabGroupType.databaseLab).length})',\n                    ),\n                  ],\n                ),\n              ),\n              AppSpacing.gapVerticalLG,\n              // عنوان القائمة\n              Row(\n                mainAxisAlignment: MainAxisAlignment.spaceBetween,\n                children: [\n                  Text(\n                    'المجموعات المتاحة (${_filteredGroups.length})',\n                    style: theme.textTheme.titleMedium?.copyWith(\n                      fontWeight: FontWeight.w700,\n                    ),\n                  ),\n                  const Text(\n                    'الفصل الحالي',\n                    style: TextStyle(\n                      fontSize: 12.0,\n                      color: AppColors.textSecondary,\n                    ),\n                  ),\n                ],\n              ),\n              AppSpacing.gapVerticalSM,\n              if (_filteredGroups.isEmpty)\n                Container(\n                  padding: AppSpacing.paddingXL,\n                  alignment: Alignment.center,\n                  decoration: BoxDecoration(\n                    color: AppColors.surface,\n                    borderRadius: BorderRadius.circular(AppRadius.radiusMD),\n                    border: Border.all(color: AppColors.border),\n                  ),\n                  child: const Column(\n                    children: [\n                      Icon(Icons.search_off_rounded, size: 48.0, color: AppColors.textSecondary),\n                      AppSpacing.gapVerticalMD,\n                      Text(\n                        'لا توجد مجموعات تطابق شروط البحث',\n                        style: TextStyle(color: AppColors.textSecondary),\n                      ),\n                    ],\n                  ),\n                )\n              else\n                ..._filteredGroups.map(\n                  (group) => LabGroupCard(\n                    group: group,\n                    onRosterTap: () => _navigateToLabAttendance(group),\n                    onStartSessionTap: () {\n                      if (group.isLiveNow) {\n                        _navigateToLabAttendance(group);\n                      } else {\n                        _handleStartSession(group);\n                      }\n                    },\n                  ),\n                ),\n              AppSpacing.gapVerticalXL,\n            ],\n          ),\n        ),\n      ),\n    );\n  }\n\n  Widget _buildFilterChip(String key, String label) {\n    final isSelected = _selectedFilter == key;\n    return ChoiceChip(\n      label: Text(label),\n      selected: isSelected,\n      onSelected: (selected) {\n        if (selected) {\n          setState(() {\n            _selectedFilter = key;\n            _applyFilters();\n          });\n        }\n      },\n      selectedColor: const Color(0xFF0F766E),\n      backgroundColor: AppColors.surface,\n      labelStyle: TextStyle(\n        color: isSelected ? Colors.white : AppColors.textPrimary,\n        fontWeight: isSelected ? FontWeight.w700 : FontWeight.w500,\n        fontSize: 12.0,\n      ),\n      shape: RoundedRectangleBorder(\n        borderRadius: BorderRadius.circular(AppRadius.radiusSM),\n        side: BorderSide(\n          color: isSelected ? const Color(0xFF0F766E) : AppColors.border,\n        ),\n      ),\n      showCheckmark: false,\n    );\n  }\n}\n